    public static int intToIntPower(int a, int b) {
	if (b <= 0) {
	    if (b == 0 || a == 1) return 1;
	    else if (a < 0) throw Utility.makeFortressException("fortress.CompilerBuiltin$DivisionByZero");
	    else return 0;
